public class EgyptianFraction {
    static void printEgyptian(int num, int den) {
        if (den == 0 || num == 0) return;
        if (den % num == 0) { System.out.println("1/" + den/num); return; }
        if (num % den == 0) { System.out.println(num/den); return; }
        if (num > den) {
            System.out.println(num/den + " + ");
            printEgyptian(num%den, den); return;
        }
        int x = den/num + 1;
        System.out.print("1/" + x + " + ");
        printEgyptian(num*x - den, den*x);
    }
    public static void main(String[] args) { printEgyptian(6, 14); }
}

